package cl.robermotos.delivery.controller;
import cl.robermotos.delivery.service.TrackingService; import cl.robermotos.delivery.model.DeliveryStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/webhooks") public class WebhookController {private final TrackingService tracking; public WebhookController(TrackingService t){tracking=t;} @PostMapping({"/uber","/pedidosya","/rappi"}) public Map<String,String> receive(@RequestBody Map<String,String> body){String id=body.get("orderId"); String raw=body.getOrDefault("status","BUSCANDO_REPARTIDOR").toUpperCase(); DeliveryStatus s=normalize(raw); tracking.update(id,s); return Map.of("received","true","orderId",id,"status",s.name());} private DeliveryStatus normalize(String s){if(s.contains("ASSIGN")||s.contains("REPARTIDOR_ASIGNADO"))return DeliveryStatus.REPARTIDOR_ASIGNADO;if(s.contains("PICK")||s.contains("RETIR"))return DeliveryStatus.RETIRADO;if(s.contains("TRANSIT")||s.contains("CAMINO"))return DeliveryStatus.EN_CAMINO;if(s.contains("DELIVER")||s.contains("ENTREG"))return DeliveryStatus.ENTREGADO;if(s.contains("CANCEL"))return DeliveryStatus.CANCELADO;return DeliveryStatus.BUSCANDO_REPARTIDOR;} }